styles.css:
.cb-brand { font-family: var(--cb-font-editorial); font-weight: 400; letter-spacing: .025em; }
.cb-brand img { background: #f5f0e7; }
.oc-hero { display: grid; gap: 2rem; padding-block: calc(var(--cb-header-height) + 3.5rem) 4rem; }
.oc-hero-copy { min-inline-size: 0; align-self: center; }
.oc-hero h1 { max-inline-size: 11ch; margin-block: 0 1.5rem; font-size: clamp(3.25rem, 6vw, 7.5rem); line-height: 1.04; }
.oc-hero-copy > p:not(.cb-eyebrow) { max-inline-size: 38ch; color: var(--cb-text-muted); }
.oc-hero-media { margin: 0; min-inline-size: 0; overflow: hidden; }
.oc-hero-media img { inline-size: 100%; block-size: auto; aspect-ratio: 4 / 3; object-fit: cover; }
.oc-section { padding-block: var(--cb-section-space); }
.oc-section-heading { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 1rem 2rem; margin-block-end: 2rem; }
.oc-section-heading > * { margin-block: 0; }
.oc-section-heading h2 { max-inline-size: 18ch; font-size: clamp(2.25rem, 4vw, 4.5rem); }
.oc-category-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.5rem 1rem; }
.oc-category-card { display: block; min-inline-size: 0; text-decoration: none; }
.oc-category-card figure { margin-block: 0 1rem; overflow: hidden; }
.oc-category-card img { inline-size: 100%; aspect-ratio: 1; object-fit: cover; }
.oc-category-card h3 { margin-block: 1rem .5rem; font-size: clamp(1.5rem, 2.2vw, 2.5rem); }
.oc-category-card > span { display: block; margin-block-start: 1rem; font-family: var(--cb-font-editorial); font-size: clamp(1.5rem, 2.2vw, 2.5rem); line-height: 1.2; }
.oc-category-card p { margin: 0; color: var(--cb-text-muted); font-size: .875rem; }
.oc-category-card:focus-visible { outline-offset: 6px; }
.oc-benefits { display: grid; gap: 1.5rem; padding-block: 2.5rem; border-block: 1px solid var(--cb-border); }
.oc-benefits > * { min-inline-size: 0; }
.oc-benefits :is(h2, h3) { font-size: 1.375rem; margin-block-end: .75rem; }
.oc-benefits p { margin: 0; color: var(--cb-text-muted); font-size: .9375rem; }
.oc-editorial { display: grid; gap: 2rem; align-items: center; background: var(--cb-surface); padding: clamp(1.5rem, 4vw, 4rem); }
.oc-editorial-media { margin: 0; min-inline-size: 0; }
.oc-editorial-media img { inline-size: 100%; block-size: auto; }
.oc-editorial-copy { min-inline-size: 0; max-inline-size: 42ch; }
.oc-editorial h2 { font-size: clamp(2.5rem, 4vw, 4.75rem); }
.oc-editorial-copy p { color: var(--cb-text-muted); }
@media (min-width: 40rem) { .oc-category-grid { gap: 2rem; } .oc-benefits { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2rem; } }
@media (min-width: 52rem) { .oc-hero { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: clamp(2rem, 5vw, 6rem); padding-block-end: 5rem; } .oc-hero-copy { grid-column: 2; grid-row: 1; } .oc-hero-media { grid-column: 1; grid-row: 1; } .oc-hero-media img { aspect-ratio: 4 / 5; max-block-size: 45rem; } .oc-category-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } .oc-editorial { grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: clamp(2rem, 5vw, 5rem); } }
